    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the interface id to let the fuzzer find the IERC1155MetadataURI id
    function testFuzz_property(bytes4 iface) public {
        // general admissible domain is all bytes4 values
        // Determine whether supportsInterface returns true for the well-known IERC1155MetadataURI id
        bool ok;
        try c.supportsInterface(type(IERC1155MetadataURI).interfaceId) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // The reference implementation MUST report support for IERC1155MetadataURI.interfaceId (always true).
        // The mutant that removed that check will return false for that id, so this assertion will fail on the mutant for at least that input.
