contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed account and token id; the reference contract MUST revert when account == address(0)
    function testFuzz_property(address account, uint256 tokenId) public {
        // keep domain wide; no narrowing that would exclude zero address
        // We check the observable property: calling balanceOf with account == address(0) must revert on the reference.
        if (account == address(0)) {
            bool ok;
            try c.balanceOf(account, tokenId) returns (uint256) {
                ok = true;
            } catch {
                ok = false;
            }
            // Reference: should revert => ok == false. Mutant: returns 0 => ok == true for some input (account == address(0)).
            assertTrue(!ok);
        } else {
            // For non-zero accounts the call should complete (not revert). Ensure it returns a uint (we just assert call succeeds).
            bool ok;
            try c.balanceOf(account, tokenId) returns (uint256) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
        }
    }
}

