pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: two arrays lengths and an index position and token id/value for minting to create non-zero balances
    function testFuzz_property(uint8 accountsLen, uint8 iIndex, uint256 tokenId, uint256 amount) public {
        // Keep lengths reasonable and non-zero
        uint256 len = bound(accountsLen, 1, 8);
        // ensure index to check is within bounds
        uint256 idx = bound(iIndex, 0, uint8(len - 1));

        // prepare arrays of addresses and ids
        address[] memory accounts = new address[](len);
        uint256[] memory ids = new uint256[](len);

        // populate with distinct addresses by deriving from address(this)
        for (uint256 i = 0; i < len; i++) {
            // create pseudo-unique addresses via address(uint160(uint256(keccak256(...))))
            accounts[i] = address(uint160(uint256(keccak256(abi.encodePacked(address(this), i)))));
            ids[i] = uint256(keccak256(abi.encodePacked(id, i))) % 10;
        }

        // We will mint some tokens to one of the accounts for the chosen tokenId so balanceOf is meaningful.
        // Need to create a game item and mint it. Make caller admin first by using constructor-set owner (address(this) is admin).
        // create a game item
        string memory nm = "test";
        string memory uri = "u";
        bool finite = false;
        bool transferable = true;
        uint256 itemsRemaining = 0;
        uint256 itemPrice = 0;
        uint16 dailyAllowance = 0;

        // call createGameItem as admin
        c.createGameItem(nm, uri, finite, transferable, itemsRemaining, itemPrice, dailyAllowance);

        // choose token id within created range (we created one at index 0), but tokenId param is fuzzed; normalize to existing token id 0
        uint256 useTokenId = 0;

        // mint some amount to accounts[idx] by directly calling internal-style mint via contract function mint
        // the contract's mint is internal to ERC1155; but C exposes mint(address tokenId, quantity) as public earlier. Here C.mint exists and requires tokenId < _itemCount
        // Use c.mint(tokenId, quantity) to mint to msg.sender — but we need to mint to accounts[idx]. The contract's _mint is internal; C.mint mints to msg.sender. So instead we will impersonate the target address and call mint to give them tokens.

        // ensure amount non-zero
        uint256 amt = bound(amount, 1, 1000);

        // prank as accounts[idx] and call mint to buy tokens (C.mint mints tokenId to msg.sender)
        vm.prank(accounts[idx]);
        c.mint(useTokenId, amt);

        // now call balanceOfBatch
        bool ok;
        uint256[] memory batch = new uint256[](0);
        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory res) {
            ok = true;
            batch = res;
        } catch {
            ok = false;
        }

        // The universal property: when balanceOfBatch returns successfully, for every position j it must equal balanceOf(accounts[j], ids[j]).
        // We assert that for the chosen index idx (which is fuzzed), if the call succeeded, the returned array at idx equals c.balanceOf(accounts[idx], ids[idx]).
        if (ok) {
            // single assertion required
            assertTrue(batch.length == len && batch[idx] == c.balanceOf(accounts[idx], ids[idx]));
        } else {
            // If call reverts, still assert a false condition cannot hold for reference; but to keep single assertTrue path, assertTrue(false) would always fail.
            // However balanceOfBatch in reference never reverts when accounts.length==ids.length (we ensured that), so ok should be true. Still assert a true statement: when not ok (shouldn't happen), assert false to fail test.
            assertTrue(false);
        }
    }
}

