pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: two array lengths and one tokenId/value to populate balances
    function testFuzz_property(uint8 accountsLen, uint8 idsLen, uint256 seed) public {
        // keep lengths reasonable but allow mismatch (we want to expose difference when lengths differ)
        uint256 aLen = uint256(accountsLen) % 6; // 0..5
        uint256 iLen = uint256(idsLen) % 6; // 0..5

        // build arrays (can be empty as well). We will ensure at least one account if needed by fuzzer,
        // but keep wide domain: allow zero-length arrays too.
        address[] memory accounts = new address[](aLen);
        uint256[] memory ids = new uint256[](iLen);

        // populate accounts and ids deterministically from seed
        for (uint256 j = 0; j < aLen; j++) {
            // create distinct addresses by deriving from seed
            accounts[j] = address(uint160(uint256(keccak256(abi.encodePacked(seed, j, "a")))));
        }
        for (uint256 j = 0; j < iLen; j++) {
            ids[j] = uint256(uint160(uint256(keccak256(abi.encodePacked(seed, j, "i"))))) % 10;
        }

        // To make balanceOf(accounts[k], ids[k]) well-defined we may need to mint some tokens for those addresses
        // Only mint when both arrays have elements and the index exists; we mint to matching pairs up to min length
        uint256 minLen = aLen < iLen ? aLen : iLen;
        for (uint256 j = 0; j < minLen; j++) {
            // mint some tokens of token id ids[j] to accounts[j]
            // minting in C uses internal _mint; but ERC1155 _mint is internal, so we cannot call it here.
            // Instead, we simulate balances by having the contract create items via createGameItem and then
            // call its internal mint through a public path is not available. However balanceOf reads from _balances
            // which we cannot directly modify. To keep test universally valid, we rely on default zero balances.
            // The property we check concerns returned array length, not values; zero balances are valid.
        }

        // Call balanceOfBatch and observe returned array length via try/catch to detect reverts
        bool ok;
        bytes memory ret;
        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory out) {
            ok = true;
            // ABI-encode returned uint256[] to inspect its length without additional ABI tooling
            // The encoding of dynamic array: offset (32) then length (32) then elements. We can re-encode via abi.encode
            ret = abi.encode(out);
        } catch {
            ok = false;
            ret = "";
        }

        // The universal property: when the call succeeds, the returned array length must equal accounts.length
        // (reference contract always constructs batchBalances sized by accounts.length). This is the single assertion.
        if (ok) {
            // decode length from abi-encoded dynamic uint256[]: skip 32 (offset), read next 32 as length
            // Only do this when ret has enough bytes
            if (ret.length >= 64) {
                uint256 returnedLength;
                assembly {
                    // ret points to bytes in memory; layout: [len][data]. The actual data starts at add(ret,32)
                    // abi.encode(out) yields: offset(32) at ret+32, then array length at ret+64
                    returnedLength := mload(add(ret, 64))
                }
                // single assert: returnedLength == accounts.length
                assertTrue(returnedLength == aLen);
            } else {
                // If encoding is too short, fail the assertion because we expected a valid encoded array
                assertTrue(false);
            }
        } else {
            // if call reverted, still must satisfy property vacuously? Reference contract reverts when lengths differ.
            // The reference will revert when accounts.length != ids.length; but we only assert on successful calls.
            // To keep single assertion and satisfy the harness, assertTrue(true) (no-op) is not allowed.
            // Therefore, when call reverts we assert that accounts.length != ids.length (i.e., revert is legitimate)
            // so reference behavior is consistent. This still leaves only one assert in each execution path.
            assertTrue(aLen != iLen);
        }
    }
}

